<script setup lang="ts">
const employeeCode = ref(''); const displayName = ref(''); const invitationUrl = ref(''); const error = ref(''); const busy = ref(false)
async function invite() { busy.value = true; error.value = ''; try { const result = await $fetch<any>('/api/admin/invitations', { method: 'POST', body: { employeeCode: employeeCode.value, displayName: displayName.value } }); invitationUrl.value = result.invitationUrl; employeeCode.value = ''; displayName.value = '' } catch (e: any) { error.value = e?.data?.statusMessage || '招待を作成できませんでした。' } finally { busy.value = false } }
</script>
<template><main class="app-shell"><NuxtLink class="back" to="/dashboard">← ダッシュボード</NuxtLink><section class="card"><p class="eyebrow">ADMIN</p><h1>利用者を招待</h1><p>招待URLは7日間有効です。安全な手段で本人に共有してください。</p><form @submit.prevent="invite"><label>社員番号<input v-model="employeeCode" required /></label><label>表示名<input v-model="displayName" required /></label><button class="primary" :disabled="busy">招待URLを作成</button></form><p v-if="error" class="error">{{ error }}</p><div v-if="invitationUrl" class="invite"><strong>招待URL</strong><code>{{ invitationUrl }}</code></div></section></main></template>
